# Define entry and exit rules
def long_entry(row):
  return row['stochastic_%k'] > row['stochastic_%d'] and row['price'] > row['ma']

def short_entry(row):
  return row['stochastic_%k'] < row['stochastic_%d'] and row['price'] < row['ma']

def long_exit(row):
